export function PollWidget({ poll: initial }) {
  const [poll, setPoll] = React.useState(initial);
  const total = poll.options.reduce((s,o)=>s+o.votes,0);
  const voted = React.useRef(localStorage.getItem("poll:"+poll.id));

  const vote = id => {
    if (voted.current) return;
    const prev = poll;
    setPoll(p => ({ ...p, options: p.options.map(o=> o.id===id?{...o, votes:o.votes+1}:o), votedId:id }));
    voted.current = id; localStorage.setItem("poll:"+poll.id, id);
    apiVote(poll.id, id).catch(()=> { setPoll(prev); voted.current=null; localStorage.removeItem("poll:"+poll.id); });
  };

  return (
    <div role="group" aria-label={poll.question}>
      <h3>{poll.question}</h3>
      {poll.options.map(o => {
        const pct = total ? Math.round(o.votes/total*100) : 0;
        return (
          <button key={o.id} onClick={()=>vote(o.id)} disabled={!!voted.current} aria-pressed={poll.votedId===o.id}>
            <span>{o.label}</span>
            <div className="track"><div className="bar" style={{ width: pct+"%" }} /></div>
            <span>{pct}% ({o.votes})</span>
          </button>
        );
      })}
      <p>{total} votes {poll.expiresAt && <Countdown to={poll.expiresAt} />}</p>
    </div>
  );
}
