export function SplitPane({ children, direction="horizontal", minSize=100 }) {
  const [sizes, setSizes] = React.useState([50, 50]);
  const containerRef = React.useRef();
  const isHoriz = direction === "horizontal";

  const onPointerDown = (idx, e) => {
    e.currentTarget.setPointerCapture(e.pointerId);
    const start = isHoriz ? e.clientX : e.clientY;
    const startSizes = [...sizes];
    const total = isHoriz ? containerRef.current.offsetWidth : containerRef.current.offsetHeight;
    const onMove = ev => {
      const deltaPct = ((isHoriz?ev.clientX:ev.clientY) - start) / total * 100;
      const next = [...startSizes];
      next[idx] = Math.max(minSize/total*100, startSizes[idx] + deltaPct);
      next[idx+1] = Math.max(minSize/total*100, startSizes[idx+1] - deltaPct);
      setSizes(next);
    };
    const onUp = () => { window.removeEventListener("pointermove", onMove); window.removeEventListener("pointerup", onUp); };
    window.addEventListener("pointermove", onMove);
    window.addEventListener("pointerup", onUp);
  };

  return (
    <div ref={containerRef} style={{ display: "flex", flexDirection: isHoriz?"row":"column", height: "400px" }}>
      {React.Children.map(children, (child, i) => (
        <>
          <div style={{ flex: `0 0 ${sizes[i]}%`, overflow: "auto" }}>{child}</div>
          {i < children.length-1 && <div role="separator" aria-orientation={isHoriz?"vertical":"horizontal"}
            onPointerDown={e=>onPointerDown(i,e)} onDoubleClick={()=>setSizes([50,50])}
            style={{ [isHoriz?"width":"height"]: 8, cursor: isHoriz?"col-resize":"row-resize", background: "#e5e7eb" }} />}
        </>
      ))}
    </div>
  );
}
```

