export function Tabs({ tabs, defaultId }) {
  const [active, setActive] = React.useState(() => new URLSearchParams(location.search).get("tab") || defaultId);
  const visited = React.useRef(new Set([active]));
  visited.current.add(active);
  React.useEffect(() => {
    const url = new URL(location.href); url.searchParams.set("tab", active);
    history.replaceState(null, "", url);
  }, [active]);

  return (
    <div role="tablist">
      {tabs.map(t => (
        <button key={t.id} role="tab" aria-selected={active===t.id} onClick={()=>setActive(t.id)}
          onKeyDown={e=>{
            const idx=tabs.findIndex(x=>x.id===active);
            if(e.key==="ArrowRight") setActive(tabs[(idx+1)%tabs.length].id);
            if(e.key==="ArrowLeft") setActive(tabs[(idx-1+tabs.length)%tabs.length].id);
          }}>
          {t.label}
        </button>
      ))}
      {tabs.map(t=> visited.current.has(t.id) && (
        <div key={t.id} role="tabpanel" hidden={active!==t.id}>{t.panel}</div>
      ))}
    </div>
  );
}
