const ToastCtx = React.createContext();
export function ToastProvider({ children }) {
  const [toasts, setToasts] = React.useState([]);
  const add = (msg, type="info") => {
    const id = Date.now();
    setToasts(t=>[...t, { id, msg, type }]);
    setTimeout(()=> setToasts(t=>t.filter(x=>x.id!==id)), 3000);
  };
  return (
    <ToastCtx.Provider value={{ toast: { success: m=>add(m,"success"), error: m=>add(m,"error") } }}>
      {children}
      {ReactDOM.createPortal(
        <div className="toast-stack" role="region" aria-live="polite">
          {toasts.slice(0,3).map(t=> <div key={t.id} role="status" className={`toast ${t.type}`}>{t.msg}<button onClick={()=>setToasts(v=>v.filter(x=>x.id!==t.id))}>×</button></div>)}
        </div>, document.body)}
    </ToastCtx.Provider>
  );
}
