function getMonthGrid(y, m) {
  const first = new Date(y, m, 1).getDay();
  const days = new Date(y, m+1, 0).getDate();
  return [...Array(first).fill(null), ...Array.from({length:days},(_,i)=> new Date(y,m,i+1))];
}

export function DatePicker({ value, onChange, mode="single" }) {
  const [cursor, setCursor] = React.useState(value || new Date());
  const y=cursor.getFullYear(), mo=cursor.getMonth();
  const grid=getMonthGrid(y,mo);
  return (
    <div role="grid" aria-label="Calendar">
      <button onClick={()=>setCursor(new Date(y, mo-1, 1))}>‹</button>
      <span>{cursor.toLocaleString("default",{month:"long",year:"numeric"})}</span>
      <button onClick={()=>setCursor(new Date(y, mo+1, 1))}>›</button>
      <div style={{display:"grid", gridTemplateColumns:"repeat(7,1fr)"}}>
        {grid.map((d,i)=> d ? <button key={i} role="gridcell" aria-selected={isSelected(d,value)}
          onClick={()=>onChange(mode==="range"? updateRange(value,d):d)}>{d.getDate()}</button> : <span key={i}/> )}
